let fishes = []
let bubbles = []
let overallTexture
let cnv
let theShader; 
let whirls = []
let whirlCount = 40
let bgGraphics
let fishGraphics

function preload(){
	theShader = createShader(vert, frag)
}

function setup() {
	cnv = createCanvas(1112, 834);

	bgGraphics = createGraphics(width,height,WEBGL);
	fishGraphics = createGraphics(width,height);

	pixelDensity(2)
	background(100);
	fill(0)
	rect(0,0,width,height)

	overAllTexture=createGraphics(width,height)

	overAllTexture.loadPixels()

	// noStroke()
	for(var i=0;i<width+50;i++){
		for(var o=0;o<height+50;o++){
			overAllTexture.set(i,o,color(200,noise(i/10,i*o/300)*random([1,10,50,100])))
		}
	}
	overAllTexture.updatePixels()

	for(var i=0;i<whirlCount;i++){
		let p = createVector(random(),random()); 
		whirls.push({
			id: random(100000),
			p: p,
			r: random(0.5,0.9),
			distortForce: random()*random(0.,0.2),
		})
		lastP = p
	}
	fishes.push(new Fish({
		p: createVector(width/2,height/2),
		size: createVector(width*0.4,height*0.2)
	}))
}

function draw() {
	bgGraphics.shader(theShader)
	fishGraphics.fill(0,10)
	fishGraphics.rect(0,0,width,height)

	let arr = whirls.map(b=>([b.p.x,b.p.y,b.distortForce,b.r]))
	let passData = []
	arr.forEach(a=>passData=passData.concat(a))

	whirls.forEach( (w,wid)=>{
		w.r = sin(wid+frameCount/30)/2.+0.5
	})
	theShader.setUniform('u_resolution',[width/1000,height/1000])
	theShader.setUniform('u_time',millis()/1000)
	theShader.setUniform('u_mouse',[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width,(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height])
	theShader.setUniform('u_noise_pan',[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width+frameCount/5000+2,(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height+-2])


	theShader.setUniform('whirls',passData)

	bgGraphics.rect(0,0,width,height)
	image(bgGraphics,0,0)
	push()
		fishGraphics.push()
			fishGraphics.blendMode(SCREEN)
			fishGraphics.image(bgGraphics,0,0)	
		fishGraphics.pop()
		fishGraphics.image(fishGraphics,1,sin(frameCount/10),width,height)
		image(fishGraphics,0,0)
		image(fishGraphics,0,0)
		image(fishGraphics,0,0)
	pop()

	fishes.forEach(fish=>{
		fish.update()
		fish.draw(fishGraphics)
	})

	push() 
		fishGraphics.blendMode(MULTIPLY)
		fishGraphics.image(overAllTexture,0,0)
	pop() 

}

